import{z as l,x as d,o as n,c as p,q as t,j as i,D as r,d as e,s,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"DMA 一致性","description":"","frontmatter":{"title":"DMA 一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dma-coherence.md","filePath":"cs/dma-coherence.md","lastUpdated":1791063341000}'),M={name:"cs/dma-coherence.md"};function c(B,a,m,D,C,h){const o=d("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="dma-一致性" tabindex="-1">DMA 一致性 <a class="header-anchor" href="#dma-一致性" aria-label="Permalink to &quot;DMA 一致性&quot;">​</a></h1><div class="epigraph"><p>设备 DMA 绕过 CPU 缓存：驱动必须 map/unmap 或用一致映射，否则 CPU 看见的是旧行，设备看见的是旧内存。</p><footer>—— 据 Linux DMA-API 文档；PCI 与 IOMMU 对地址翻译的说明</footer></div><p><a href="/cs/kernel-hardening">加固</a> 不管设备。<a href="/cs/nvme-driver">NVMe</a>/<a href="/cs/napi">NIC</a> 都靠 DMA。<a href="/cs/direct-map-highmem">直接映射</a> 给 CPU 看 RAM。缺口是 <strong>DMA API</strong>：流式映射、一致缓冲、IOMMU 保护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存层次对设备不可见。流式：<code>dma_map_sg</code> 前 <code>cpu_to_dev</code> 刷或作废缓存，完成后 <code>dev_to_cpu</code>。一致：<code>dma_alloc_coherent</code> 非缓存或硬件嗅探。缺口：IOMMU 把设备地址限制在 map 的窗口，防乱 DMA；bounce buffer 给不能到达高物理地址的卡。本课不把每架构 cache line 维护指令写完。</p><p><span class="marginnote">直觉类比：把 CPU 缓存想成你桌上的便签，内存是档案柜。设备 DMA 直接去档案柜翻文件，看不见你桌上还没归档的便签；反过来设备改了柜子，你桌上的旧便签也不会自动更新。map/unmap 就是「归档」和「作废便签」这两个动作。</span></p><p><span class="marginnote">VFIO 用户态 DMA 仍走 IOMMU 域。无 IOMMU 时设备信任基等于内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动提交 I/O：map 页给设备，门铃，完成 interrupt 后 unmap。对照 <a href="/cs/rdma-os">RDMA</a> MR：同类「允许 DMA 的窗口」。对照 <a href="/cs/write-barrier-fua">FUA</a>：那是持久；这是缓存可见性。对照 KPTI：CPU 页表，不是 IOMMU 页表。</p><p><span class="marginnote">术语翻译：IOMMU 就是「给设备用的 MMU」——CPU 用页表把虚拟地址译成物理地址，IOMMU 用自己的页表把设备地址译成物理地址，且只放行登记过的窗口。没有它，任何能发地址的卡理论上都能改写整机内存。</span></p>',10)),(n(),i(A,null,{default:r(()=>[s(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20%E7%BC%93%E5%AD%98%22%5D%20--%3E%20SYNC%5B%22dma_map%20%E5%90%8C%E6%AD%A5%22%5D%0A%20%20SYNC%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%20DMA%22%5D%0A%20%20IOMMU%5B%22IOMMU%22%5D%20--%3E%20WIN%5B%22%E4%BB%85%E5%85%81%E8%AE%B8%E6%98%A0%E5%B0%84%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("DMA API 把「设备是另一个观察者」收成驱动义务，使块与网的完成含义正确。IOMMU 把义务加上隔离。不要写成 MESI 协议课全文。与 "),E("a",{href:"/cs/memory-hotplug"},"热插拔"),e("：offline 前必须无 DMA。")],-1)),(n(),i(A,null,{default:r(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T2D%5B%22TO_DEVICE%EF%BC%9ACPU%20%E5%86%99%E5%A5%BD%E4%BA%A4%E7%BB%99%E8%AE%BE%E5%A4%87%22%5D%20--%3E%20F1%5B%22map%20%E6%97%B6%E6%8A%8A%20CPU%20%E7%BC%93%E5%AD%98%E5%88%B7%E8%BF%9B%E5%86%85%E5%AD%98%22%5D%0A%20%20F1%20--%3E%20B1%5B%22%E6%BC%8F%E5%88%B7%EF%BC%9A%E8%AE%BE%E5%A4%87%E8%AF%BB%E5%88%B0%E6%97%A7%E6%95%B0%E6%8D%AE%22%5D%0A%20%20F2D%5B%22FROM_DEVICE%EF%BC%9A%E8%AE%BE%E5%A4%87%E5%86%99%E7%BB%99%20CPU%22%5D%20--%3E%20F2%5B%22unmap%20%E6%97%B6%E6%8A%8A%E7%BC%93%E5%AD%98%E8%A1%8C%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20F2%20--%3E%20B2%5B%22%E6%BC%8F%E4%BD%9C%E5%BA%9F%EF%BC%9ACPU%20%E8%AF%BB%E5%88%B0%E8%87%AA%E5%B7%B1%E7%BC%93%E5%AD%98%E9%87%8C%E7%9A%84%E6%97%A7%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>错误：漏 unmap 泄漏 IOMMU 表；过早 unmap 损坏。</p><p><span class="marginnote">为什么重要：TO_DEVICE 误写成 FROM_DEVICE，编译器不报错、程序多半还能跑——只是偶发读到旧数据。这类方向参数写错导致的静默损坏，症状往往出现在离写错处很远的设备另一端，是驱动里最难复现的一类 bug。</span></p><p>实现上：流式映射的方向错了会静默损坏：TO_DEVICE 必须刷 CPU 缓存。IOMMU 组把无法隔离的设备绑在一起，VFIO 必须整组给同一用户。swiotlb 是 32 位 DMA 的 bounce。 读法上只引用<a href="/cs/kernel-hardening">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>DMA 一致性</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DMA-BUF 跨设备共享的全部。不保证所有 virtio 的 bounce。下一课 CPU 内存标签：MTE。</p><p>版本字段会变，课序钉的是机制对象「DMA 一致性」，不是某一主线内核的结构体名。 后课默认：DMA 必须经 map 与可选 IOMMU。用标签检测空间错误，下一课 MTE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DMA 与 CPU 缓存要显式同步或一致映射。</li><li>IOMMU 限制设备可写的物理窗口。</li><li>内存标签是下一课。</li><li>出处：Linux DMA-API；IOMMU；PCI。</li></ul>',10))])}const I=l(M,[["render",c]]);export{_ as __pageData,I as default};
